{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "oneOf": [
    {
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "JMESPath": {
          "type": "string"
        }
      },
      "required": [
        "JMESPath"
      ],
      "additionalProperties": false
    },
    {
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "Starlark": {
          "type": "string"
        }
      },
      "required": [
        "Starlark"
      ],
      "additionalProperties": false
    },
    {
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "Special": {
          "$ref": "functions.expression.Special"
        }
      },
      "required": [
        "Special"
      ],
      "additionalProperties": false
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  },
  "required": [
    "anyOf"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "oneOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "const": "image_url"
        }
      },
      "required": [
        "type",
        "image_url"
      ]
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "const": "input_audio"
        }
      },
      "required": [
        "type",
        "input_audio"
      ]
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "input_video"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "video_url"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "const": "file"
        }
      },
      "required": [
        "type",
        "file"
      ]
    }
  ]
}
